  /// A background shell job started (`bash` background): the board
  /// registers the live card (issue #429). Line mode prints nothing here —
  /// the terminal card carries the truth at settle; TUI mode shows the
  /// live region.
  void _onShellJobStarted(ShellJobEntry job) {
    _jobBoard.start(
      TaskBlock(
        kind: 'bash',
        id: job.id,
        state: TaskBlockState.running,
        label: job.command,
      ),
    );
    _jobBoardAfterMutation();
    // Event-driven waiting-row enter (issue #450).
    unawaited(_waiting.jobStarted(job));
  }

  /// A background shell job settled: truthful terminal state in place —
  /// done/failed/timed out/stopped/lost, never "running" forever.
  void _onShellJobSettledBlock(ShellJobEntry job) {
    final state = shellJobPhaseOf(
      isRunning: job.isRunning,
      exitCode: job.exitCode,
      stopReason: job.stopReason,
    );
    if (!taskBlockStateIsTerminal(state)) return;
    _jobBoard.settle(
      job.id,
      state: state,
      elapsed: DateTime.now().difference(job.startedAt).inMilliseconds / 1000,
      exitCode: job.exitCode,
      detail: shellJobCardDetail(
        id: job.id,
        cwd: job.cwd,
        logPath: job.logPath,
        state: state,
        exitCode: job.exitCode,
        // AC9: the log face's budget keeps a long `log:` path whole.
        maxLength: _cardDetailMaxLength,
      ),
    );
    _jobBoardAfterMutation();
  }

  /// After every board mutation: drain terminal material into the
  /// transcript, refresh the TUI's live region, persist the records.
  void _jobBoardAfterMutation() {
    _printBoardLines(
      _jobBoard.takeTranscriptLines(width: _hubBlockWidth, fit: _cardTextFit),
    );
    _tuiController?.setJobBoard(_jobBoard.liveLines(width: _hubBlockWidth));
    unawaited(_persistJobBoard());
  }

  /// Persists the board as `shell_job_registry` custom records (issue #429
  /// AC9): a resumed session rebuilds from these and never shows "running".
  ///
  /// Issue #539: the writes are CHAINED — a wave of near-simultaneous job
  /// starts fires one persist per mutation, and un-chained appends can land
  /// out of order. A stale snapshot finishing LAST would win
  /// `latestRecords` on resume: 4 of 5 running jobs silently vanished from
  /// the registry (observed: "1 background task lost" for 5 live jobs).
  /// Chained, the last queued write carries the newest snapshot.
  ///
  /// gh-1073: a byte-identical snapshot is skipped — the ledger is
  /// latest-snapshot-wins, so re-appending unchanged payloads only grew
  /// the session file (29k snapshots = 3.65 GB on the ticket's session).
  ///
  /// gh-1590: the appends are also RATE-BOUNDED — only the first board
  /// mutation inside a persist window ([ledgerSnapshotPersistInterval])
  /// appends; the rest coalesce behind the trailing flush leg, because
  /// only the latest snapshot is ever read. `force` bypasses the window
  /// for the shutdown flush — the final state must reach the file even
  /// when the mutations never stopped (the deduper still suppresses a
  /// no-op flush).
  Future<void> _persistJobBoard({bool force = false}) {
    final session = _session;
    if (session == null) return Future.value();
    _persistChain = _persistChain
        .then((_) async {
          // A board with no cards has nothing to say: an empty `[]`
          // snapshot must not append (every no-job session would grow
          // one at run finalize) and must not open a persist window.
          // The check rides BEFORE the gate so it costs nothing when
          // the window would refuse anyway.
          final records = _jobBoard.toRecords();
          if (records.isEmpty) return;
          // gh-1590: the window gate NEXT — a refused mutation reserves
          // the trailing flush (which re-enters here unforced) and skips
          // the encode entirely.
          if (!force && !_jobBoardPersistThrottle.shouldPersistNow()) return;
          // Serialize ONCE — the dedupe key must be the exact payload
          // that gets appended, not a second encoding of the same board.
          final json = jsonEncode(records);
          if (!_jobBoardPersistDeduper.shouldPersist(json)) return;
          try {
            await session.appendCustomEntry(
              customType: 'shell_job_registry',
              data: records,
            );
            _jobBoardPersistDeduper.confirmPersisted();
            _jobBoardPersistThrottle.confirmPersisted();
          } on Object {
            // The chain swallows below by design; roll the deduper back
            // first so the retried identical snapshot is NOT skipped.
            _jobBoardPersistDeduper.revertFailedPersist();
            rethrow;
          }
        })
        // One failed append must not poison the chain (every later persist
        // would be skipped) nor escape as an unhandled zone error — the
        // next mutation retries with a fresh snapshot.
        .catchError((_) {});
    return _persistChain;
  }

  /// Rebuilds the board from the resumed session's records. Jobs that were
  /// live at restart print their lost card after the transcript replay —
  /// prominent, not silent.
  Future<void> _rehydrateJobBoard() async {
    final session = _session;
    if (session == null) return;
    // gh-1590: the persist window opens with the (re)hydrated session —
    // BEFORE the empty-ledger early return, so a session switch never
    // inherits the previous session's window.
    _jobBoardPersistThrottle.reset();
    final latest = ShellJobBoard.latestRecords(await session.getEntries());
    if (latest.isEmpty) return;
    _jobBoard = ShellJobBoard.rehydrated(latest);
    // Fresh session file content: the next persist is a new snapshot, not
    // a repeat of whatever the previous session last wrote (gh-1073).
    _jobBoardPersistDeduper.reset();
    _printBoardLines(
      _jobBoard.takeTranscriptLines(width: _hubBlockWidth, fit: _cardTextFit),
    );
